[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Global Aid Alliance — Together We Respond</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --red-primary: #C41E3A;
      --red-dark: #9B1830;
      --red-light: #E63950;
      --navy: #1B3A5C;
      --navy-dark: #0F2439;
      --white: #FFFFFF;
      --gray-50: #F8F9FA;
      --gray-100: #F1F3F5;
      --gray-200: #E9ECEF;
      --gray-300: #DEE2E6;
      --gray-400: #CED4DA;
      --gray-500: #ADB5BD;
      --gray-600: #6C757D;
      --gray-700: #495057;
      --gray-800: #343A40;
      --gray-900: #212529;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
      --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);
      --transition-fast: 150ms ease;
      --transition-normal: 250ms ease;
      --transition-slow: 350ms ease;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      font-size: 16px;
      line-height: 1.6;
      color: var(--gray-900);
      background: var(--white);
      -webkit-font-smoothing: antialiased;
    }

    /* Skip Link */
    .skip-link {
      position: absolute;
      top: -100%;
      left: 16px;
      padding: 12px 24px;
      background: var(--red-primary);
      color: white;
      text-decoration: none;
      border-radius: 4px;
      z-index: 9999;
      transition: top var(--transition-fast);
    }
    .skip-link:focus {
      top: 16px;
    }

    /* Container */
    .container {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* Header */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      background: var(--white);
      border-bottom: 1px solid var(--gray-200);
      z-index: 100;
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      text-decoration: none;
      color: var(--navy);
    }

    .logo-icon {
      width: 40px;
      height: 40px;
      background: var(--red-primary);
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg {
      width: 24px;
      height: 24px;
      color: white;
    }

    .logo-text {
      font-weight: 700;
      font-size: 18px;
    }

    .nav-desktop {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 28px;
      list-style: none;
    }

    .nav-links a {
      color: var(--gray-700);
      text-decoration: none;
      font-size: 15px;
      font-weight: 500;
      transition: color var(--transition-fast);
    }

    .nav-links a:hover {
      color: var(--red-primary);
    }

    .nav-utils {
      display: flex;
      align-items: center;
      gap: 16px;
      margin-left: 24px;
      padding-left: 24px;
      border-left: 1px solid var(--gray-200);
    }

    .nav-utils a {
      color: var(--gray-600);
      text-decoration: none;
      font-size: 14px;
      transition: color var(--transition-fast);
    }

    .nav-utils a:hover {
      color: var(--red-primary);
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 12px 24px;
      font-size: 15px;
      font-weight: 600;
      text-decoration: none;
      border-radius: 8px;
      border: none;
      cursor: pointer;
      transition: all var(--transition-fast);
    }

    .btn:focus-visible {
      outline: 3px solid var(--red-primary);
      outline-offset: 2px;
    }

    .btn-primary {
      background: var(--red-primary);
      color: white;
    }

    .btn-primary:hover {
      background: var(--red-dark);
      transform: translateY(-1px);
      box-shadow: var(--shadow-md);
    }

    .btn-secondary {
      background: var(--navy);
      color: white;
    }

    .btn-secondary:hover {
      background: var(--navy-dark);
    }

    .btn-outline {
      background: transparent;
      color: var(--red-primary);
      border: 2px solid var(--red-primary);
    }

    .btn-outline:hover {
      background: var(--red-primary);
      color: white;
    }

    .btn-lg {
      padding: 16px 32px;
      font-size: 17px;
    }

    /* Hamburger */
    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
      margin-right: -8px;
    }

    .hamburger:focus-visible {
      outline: 3px solid var(--red-primary);
      outline-offset: 2px;
      border-radius: 4px;
    }

    .hamburger span {
      display: block;
      width: 24px;
      height: 2px;
      background: var(--gray-800);
      border-radius: 2px;
      transition: all var(--transition-fast);
    }

    /* Mobile Menu */
    .mobile-menu {
      display: none;
      position: fixed;
      top: 72px;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--white);
      z-index: 99;
      overflow-y: auto;
    }

    .mobile-menu.open {
      display: block;
    }

    .mobile-menu-inner {
      padding: 24px;
    }

    .mobile-nav-links {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 4px;
    }

    .mobile-nav-links a {
      display: block;
      padding: 14px 16px;
      color: var(--gray-800);
      text-decoration: none;
      font-size: 16px;
      font-weight: 500;
      border-radius: 8px;
      transition: background var(--transition-fast);
    }

    .mobile-nav-links a:hover {
      background: var(--gray-100);
    }

    .mobile-nav-links .btn {
      width: 100%;
      margin-top: 16px;
    }

    .mobile-utils {
      margin-top: 24px;
      padding-top: 24px;
      border-top: 1px solid var(--gray-200);
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
    }

    .mobile-utils a {
      color: var(--gray-600);
      text-decoration: none;
      font-size: 14px;
    }

    /* Hero */
    .hero {
      padding: 140px 0 100px;
      background: linear-gradient(135deg, var(--gray-50) 0%, var(--white) 100%);
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: 0;
      right: 0;
      width: 50%;
      height: 100%;
      background: linear-gradient(135deg, transparent 0%, rgba(196, 30, 58, 0.03) 100%);
      pointer-events: none;
    }

    .hero-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }

    .hero-content {
      max-width: 560px;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 16px;
      background: rgba(196, 30, 58, 0.08);
      color: var(--red-primary);
      font-size: 14px;
      font-weight: 600;
      border-radius: 100px;
      margin-bottom: 24px;
    }

    .hero-title {
      font-size: 56px;
      font-weight: 800;
      line-height: 1.1;
      color: var(--navy);
      margin-bottom: 24px;
      letter-spacing: -0.02em;
    }

    .hero-subtitle {
      font-size: 20px;
      color: var(--gray-600);
      line-height: 1.6;
      margin-bottom: 36px;
    }

    .hero-ctas {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
    }

    .hero-image {
      position: relative;
      border-radius: 16px;
      overflow: hidden;
      box-shadow: var(--shadow-xl);
      aspect-ratio: 4/3;
      background: var(--gray-200);
    }

    .hero-image img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .hero-image-placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      background: linear-gradient(135deg, var(--gray-100) 0%, var(--gray-200) 100%);
      color: var(--gray-400);
      font-size: 14px;
    }

    /* Mission */
    .mission {
      padding: 100px 0;
      background: var(--white);
    }

    .mission-inner {
      max-width: 800px;
      margin: 0 auto;
      text-align: center;
    }

    .section-label {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 13px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--red-primary);
      margin-bottom: 20px;
    }

    .section-label::before,
    .section-label::after {
      content: '';
      width: 20px;
      height: 2px;
      background: var(--red-primary);
      border-radius: 1px;
    }

    .mission-title {
      font-size: 40px;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 28px;
      line-height: 1.2;
    }

    .mission-text {
      font-size: 18px;
      color: var(--gray-600);
      line-height: 1.8;
    }

    /* Impact Stats */
    .impact {
      padding: 80px 0;
      background: var(--navy);
      color: white;
    }

    .impact-inner {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 48px;
    }

    .impact-stat {
      text-align: center;
    }

    .impact-number {
      font-size: 56px;
      font-weight: 800;
      color: white;
      line-height: 1;
      margin-bottom: 12px;
      font-variant-numeric: tabular-nums;
    }

    .impact-number .suffix {
      font-size: 40px;
    }

    .impact-label {
      font-size: 16px;
      color: rgba(255,255,255,0.7);
      font-weight: 500;
    }

    /* Programs */
    .programs {
      padding: 100px 0;
      background: var(--gray-50);
    }

    .programs-header {
      text-align: center;
      margin-bottom: 56px;
    }

    .programs-title {
      font-size: 40px;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 16px;
    }

    .programs-subtitle {
      font-size: 18px;
      color: var(--gray-600);
    }

    .accordion {
      max-width: 900px;
      margin: 0 auto;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .accordion-item {
      background: var(--white);
      border-radius: 12px;
      border: 1px solid var(--gray-200);
      overflow: hidden;
      transition: box-shadow var(--transition-normal);
    }

    .accordion-item:hover {
      box-shadow: var(--shadow-md);
    }

    .accordion-trigger {
      width: 100%;
      padding: 24px 28px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      background: none;
      border: none;
      cursor: pointer;
      text-align: left;
      font-size: 18px;
      font-weight: 600;
      color: var(--navy);
      transition: color var(--transition-fast);
    }

    .accordion-trigger:hover {
      color: var(--red-primary);
    }

    .accordion-trigger:focus-visible {
      outline: 3px solid var(--red-primary);
      outline-offset: -3px;
    }

    .accordion-icon {
      width: 24px;
      height: 24px;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: transform var(--transition-normal);
      flex-shrink: 0;
    }

    .accordion-icon svg {
      width: 20px;
      height: 20px;
      color: var(--gray-500);
    }

    .accordion-item.open .accordion-icon {
      transform: rotate(180deg);
    }

    .accordion-content {
      max-height: 0;
      overflow: hidden;
      transition: max-height var(--transition-slow);
    }

    .accordion-item.open .accordion-content {
      max-height: 500px;
    }

    .accordion-body {
      padding: 0 28px 28px;
      color: var(--gray-600);
      font-size: 16px;
      line-height: 1.7;
    }

    /* Get Involved */
    .get-involved {
      padding: 100px 0;
      background: var(--white);
    }

    .get-involved-header {
      text-align: center;
      margin-bottom: 56px;
    }

    .get-involved-title {
      font-size: 40px;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 16px;
    }

    .involve-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 32px;
    }

    .involve-card {
      padding: 36px 32px;
      background: var(--gray-50);
      border-radius: 16px;
      text-align: center;
      transition: all var(--transition-normal);
    }

    .involve-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .involve-icon {
      width: 64px;
      height: 64px;
      background: rgba(196, 30, 58, 0.1);
      border-radius: 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 24px;
    }

    .involve-icon svg {
      width: 32px;
      height: 32px;
      color: var(--red-primary);
    }

    .involve-card h3 {
      font-size: 22px;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 12px;
    }

    .involve-card p {
      font-size: 15px;
      color: var(--gray-600);
      margin-bottom: 24px;
      line-height: 1.6;
    }

    /* News */
    .news {
      padding: 100px 0;
      background: var(--gray-50);
    }

    .news-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: 48px;
    }

    .news-title {
      font-size: 40px;
      font-weight: 700;
      color: var(--navy);
    }

    .news-nav {
      display: flex;
      gap: 12px;
    }

    .news-nav-btn {
      width: 48px;
      height: 48px;
      border-radius: 50%;
      border: 1px solid var(--gray-300);
      background: var(--white);
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: all var(--transition-fast);
    }

    .news-nav-btn:hover {
      background: var(--red-primary);
      border-color: var(--red-primary);
      color: white;
    }

    .news-nav-btn:focus-visible {
      outline: 3px solid var(--red-primary);
      outline-offset: 2px;
    }

    .news-nav-btn svg {
      width: 20px;
      height: 20px;
    }

    .carousel {
      overflow: hidden;
      position: relative;
    }

    .carousel-track {
      display: flex;
      gap: 24px;
      transition: transform var(--transition-slow);
    }

    .news-card {
      flex: 0 0 calc(33.333% - 16px);
      background: var(--white);
      border-radius: 16px;
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      transition: all var(--transition-normal);
    }

    .news-card:hover {
      box-shadow: var(--shadow-lg);
      transform: translateY(-4px);
    }

    .news-image {
      aspect-ratio: 16/10;
      background: var(--gray-200);
      overflow: hidden;
    }

    .news-image img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .news-image-placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      background: linear-gradient(135deg, var(--gray-100) 0%, var(--gray-200) 100%);
      color: var(--gray-400);
      font-size: 12px;
    }

    .news-content {
      padding: 24px;
    }

    .news-category {
      display: inline-block;
      padding: 4px 12px;
      background: rgba(196, 30, 58, 0.1);
      color: var(--red-primary);
      font-size: 12px;
      font-weight: 600;
      border-radius: 100px;
      margin-bottom: 12px;
    }

    .news-card h3 {
      font-size: 18px;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 8px;
      line-height: 1.4;
    }

    .news-card p {
      font-size: 14px;
      color: var(--gray-600);
      line-height: 1.6;
    }

    /* Donate CTA */
    .donate-cta {
      padding: 100px 0;
      background: var(--red-primary);
      color: white;
    }

    .donate-cta-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }

    .donate-cta-content h2 {
      font-size: 44px;
      font-weight: 800;
      margin-bottom: 20px;
      line-height: 1.1;
    }

    .donate-cta-content p {
      font-size: 18px;
      opacity: 0.9;
      line-height: 1.7;
      margin-bottom: 32px;
    }

    .impact-table {
      background: rgba(255,255,255,0.1);
      border-radius: 16px;
      padding: 32px;
    }

    .impact-table h3 {
      font-size: 20px;
      font-weight: 700;
      margin-bottom: 24px;
      text-align: center;
    }

    .impact-row {
      display: flex;
      justify-content: space-between;
      padding: 12px 0;
      border-bottom: 1px solid rgba(255,255,255,0.15);
    }

    .impact-row:last-child {
      border-bottom: none;
    }

    .impact-row .amount {
      font-weight: 700;
      color: white;
    }

    .impact-row .desc {
      color: rgba(255,255,255,0.8);
      font-size: 14px;
    }

    .donate-cta-btn {
      background: white;
      color: var(--red-primary);
      margin-top: 32px;
    }

    .donate-cta-btn:hover {
      background: var(--gray-100);
    }

    /* Footer */
    .footer {
      background: var(--navy);
      color: white;
      padding: 80px 0 40px;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 2fr repeat(3, 1fr);
      gap: 48px;
      margin-bottom: 48px;
    }

    .footer-brand p {
      color: rgba(255,255,255,0.7);
      font-size: 14px;
      line-height: 1.7;
      margin-top: 20px;
      max-width: 280px;
    }

    .footer-col h4 {
      font-size: 14px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      margin-bottom: 20px;
      color: rgba(255,255,255,0.5);
    }

    .footer-col ul {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .footer-col a {
      color: rgba(255,255,255,0.8);
      text-decoration: none;
      font-size: 14px;
      transition: color var(--transition-fast);
    }

    .footer-col a:hover {
      color: white;
    }

    .footer-bottom {
      padding-top: 40px;
      border-top: 1px solid rgba(255,255,255,0.1);
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .footer-bottom p {
      color: rgba(255,255,255,0.5);
      font-size: 13px;
    }

    .footer-social {
      display: flex;
      gap: 16px;
    }

    .footer-social a {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: rgba(255,255,255,0.1);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background var(--transition-fast);
    }

    .footer-social a:hover {
      background: rgba(255,255,255,0.2);
    }

    .footer-social svg {
      width: 18px;
      height: 18px;
      color: white;
    }

    /* Donation Modal */
    .modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,0.6);
      backdrop-filter: blur(4px);
      z-index: 200;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 24px;
      opacity: 0;
      visibility: hidden;
      transition: all var(--transition-normal);
    }

    .modal-overlay.open {
      opacity: 1;
      visibility: visible;
    }

    .modal {
      background: var(--white);
      border-radius: 20px;
      max-width: 500px;
      width: 100%;
      max-height: 90vh;
      overflow-y: auto;
      transform: scale(0.95) translateY(20px);
      transition: transform var(--transition-normal);
    }

    .modal-overlay.open .modal {
      transform: scale(1) translateY(0);
    }

    .modal-header {
      padding: 28px 32px;
      border-bottom: 1px solid var(--gray-200);
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .modal-header h2 {
      font-size: 24px;
      font-weight: 700;
      color: var(--navy);
    }

    .modal-close {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      border: none;
      background: var(--gray-100);
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: background var(--transition-fast);
    }

    .modal-close:hover {
      background: var(--gray-200);
    }

    .modal-close:focus-visible {
      outline: 3px solid var(--red-primary);
      outline-offset: 2px;
    }

    .modal-close svg {
      width: 20px;
      height: 20px;
      color: var(--gray-600);
    }

    .modal-body {
      padding: 32px;
    }

    .donate-amounts {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 12px;
      margin-bottom: 24px;
    }

    .amount-option {
      padding: 16px;
      border: 2px solid var(--gray-200);
      border-radius: 12px;
      background: none;
      cursor: pointer;
      text-align: center;
      transition: all var(--transition-fast);
    }

    .amount-option:hover {
      border-color: var(--red-primary);
      background: rgba(196, 30, 58, 0.03);
    }

    .amount-option.selected {
      border-color: var(--red-primary);
      background: var(--red-primary);
      color: white;
    }

    .amount-option:focus-visible {
      outline: 3px solid var(--red-primary);
      outline-offset: 2px;
    }

    .amount-option .amount {
      font-size: 22px;
      font-weight: 700;
      display: block;
    }

    .amount-option .impact {
      font-size: 11px;
      opacity: 0.7;
      margin-top: 4px;
    }

    .custom-amount {
      margin-bottom: 24px;
    }

    .custom-amount label {
      display: block;
      font-size: 14px;
      font-weight: 600;
      color: var(--gray-700);
      margin-bottom: 8px;
    }

    .custom-amount input {
      width: 100%;
      padding: 14px 16px;
      border: 2px solid var(--gray-200);
      border-radius: 10px;
      font-size: 18px;
      font-weight: 600;
      transition: border-color var(--transition-fast);
    }

    .custom-amount input:focus {
      outline: none;
      border-color: var(--red-primary);
    }

    .donate-submit {
      width: 100%;
      padding: 16px;
      font-size: 17px;
    }

    .donate-note {
      text-align: center;
      font-size: 13px;
      color: var(--gray-500);
      margin-top: 16px;
    }

    /* Responsive */
    @media (max-width: 1024px) {
      .hero-inner {
        grid-template-columns: 1fr;
        gap: 48px;
      }

      .hero-content {
        max-width: 100%;
        text-align: center;
      }

      .hero-ctas {
        justify-content: center;
      }

      .impact-inner {
        grid-template-columns: repeat(2, 1fr);
        gap: 40px;
      }

      .involve-grid {
        grid-template-columns: 1fr;
        max-width: 480px;
        margin: 0 auto;
      }

      .donate-cta-inner {
        grid-template-columns: 1fr;
        gap: 48px;
        text-align: center;
      }

      .footer-grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }

    @media (max-width: 768px) {
      .nav-desktop {
        display: none;
      }

      .hamburger {
        display: flex;
      }

      .hero {
        padding: 120px 0 80px;
      }

      .hero-title {
        font-size: 36px;
      }

      .hero-subtitle {
        font-size: 17px;
      }

      .impact-number {
        font-size: 40px;
      }

      .impact-number .suffix {
        font-size: 28px;
      }

      .news-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 24px;
      }

      .news-card {
        flex: 0 0 100%;
      }

      .donate-cta-content h2 {
        font-size: 32px;
      }

      .footer-grid {
        grid-template-columns: 1fr;
        gap: 32px;
      }

      .footer-bottom {
